import java.util.*;
class Solution { public List<Integer> findAnagrams(String s,String p){List<Integer>r=new ArrayList<>();if(p.length()>s.length())return r;int[]a=new int[26],b=new int[26];for(char c:p.toCharArray())a[c-'a']++;for(int i=0;i<s.length();i++){b[s.charAt(i)-'a']++;if(i>=p.length())b[s.charAt(i-p.length())-'a']--;if(Arrays.equals(a,b))r.add(i-p.length()+1);}return r;} }